const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const uid=()=>crypto.randomUUID();
const baseCourses=[{id:'ai',name:'AI Alignment',code:'COMPSCI 690S',teacher:'Prof. Scott Niekum',description:'From learning by imitation to learning what we value.',site:'https://people.cs.umass.edu/~sniekum/classes/AIA-F26/',lectures:[{id:'1',title:'Behavior cloning',date:'2026-09-10',subtitle:'Learning from demonstrations'},{id:'2',title:'Limitations of behavior cloning',date:'2026-09-15',subtitle:'When imitation fails',replay:true},{id:'3',title:'Reinforcement learning',date:'2026-09-17',subtitle:'Learning through interaction'}]},{id:'cv',name:'Computer Vision',code:'COMPSCI 670',teacher:'Fall 2026',description:'A different way of seeing. From pixels to perception.',site:'https://cvl-umass.github.io/cv-fall-2026/',lectures:[{id:'1',title:'Course overview',date:'2026-09-08',subtitle:'An introduction to visual understanding'},{id:'2',title:'Cameras and geometric image formation',date:'2026-09-15',subtitle:'How the world becomes an image'},{id:'3',title:'Light, reflectance, color, and sensors',date:'2026-09-17',subtitle:'From light to pixels'}]}];
const baseSources=[{id:'ai-site',course:'ai',lecture:'all',title:'AI Alignment · course website',kind:'Website',url:baseCourses[0].site},{id:'cv-site',course:'cv',lecture:'all',title:'Computer Vision · course website',kind:'Website',url:baseCourses[1].site},...[
['ai1slides','1','Behavior cloning · lecture slides','Slides','ai-01-slides.pdf','https://people.cs.umass.edu/~sniekum/classes/AIA-F26/lectures/bc.pdf'],['ai1read','1','Behavioral Cloning from Observation','Required','ai-01-reading.pdf','https://arxiv.org/pdf/1805.01954.pdf'],['ai2slides','2','Limitations of behavior cloning · slides','Slides','ai-02-slides.pdf','https://people.cs.umass.edu/~sniekum/classes/AIA-F26/lectures/limitbc.pdf'],['ai2read','2','DAgger · Imitation Learning as No-Regret Online Learning','Required','ai-02-reading.pdf','https://proceedings.mlr.press/v15/ross11a/ross11a.pdf'],['ai3slides','3','Reinforcement learning · lecture slides','Slides','ai-03-slides.pdf','https://people.cs.umass.edu/~sniekum/classes/AIA-F26/lectures/rl.pdf'],['ai3ppo','3','Proximal Policy Optimization Algorithms','Optional','ai-03-ppo.pdf','https://arxiv.org/pdf/1707.06347.pdf']].map(([id,lecture,title,kind,pdf,url])=>({id,course:'ai',lecture,title,kind,pdf:'pdfs/'+pdf,url}))];
let userCourses=[],userSources=[],filter='All',recording=null,recordTimer,blobURLs=[];try{userCourses=JSON.parse(localStorage.getItem('recall-courses')||'[]');userSources=JSON.parse(localStorage.getItem('recall-sources')||'[]')}catch{}const courses=()=>[...baseCourses,...userCourses];const sources=(id,l)=>[...baseSources,...userSources].filter(s=>s.course===id&&(!l||s.lecture===l||s.lecture==='all'));const getCourse=id=>courses().find(c=>c.id===id);const date=s=>new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});const route=()=>location.hash.slice(1).split('/');
function save(){try{localStorage.setItem('recall-courses',JSON.stringify(userCourses));localStorage.setItem('recall-sources',JSON.stringify(userSources))}catch{notify('Storage is unavailable. Changes will last for this session.')}}function notify(t){$('#notice').textContent=t;$('#notice').classList.add('show');setTimeout(()=>$('#notice').classList.remove('show'),3200)}function modal(html,wide=false){$('#dialog').classList.toggle('wide',wide);$('#dialogBody').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}$('#closeDialog').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('close',()=>{blobURLs.forEach(URL.revokeObjectURL);blobURLs=[]});$('#dialog').onclick=e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
function page(html,crumb){$('#page').innerHTML=html;$('#breadcrumb').innerHTML=crumb;window.scrollTo(0,0);bind()}const foot=()=>'<div class="bottom-note"><span>A little rewind. A lot of clarity.</span><span>Interactive prototype · No background AI connected</span></div>';
function art(vision){return `<div class="orb" aria-hidden="true"><svg viewBox="0 0 260 260">${vision?'<path d="M42 42h176v176H42zM64 64h132v132H64zM87 87h86v86H87z" fill="none"/><circle cx="130" cy="130" r="24"/>':'<ellipse cx="130" cy="130" rx="94" ry="44" transform="rotate(35 130 130)"/><ellipse cx="130" cy="130" rx="94" ry="44" transform="rotate(-35 130 130)"/><circle cx="130" cy="130" r="67"/><circle cx="130" cy="130" r="6" class="star"/>'}</svg></div>`}
function render(){const [view,id,lid]=route();if(!view||view==='courses'){renderCourses();return}const c=getCourse(id);if(!c){location.hash='courses';return}if(view==='course')renderCourse(c);else if(view==='sources')renderSources(c);else if(view==='lecture'){const l=c.lectures.find(l=>l.id===lid);if(l)renderLecture(c,l);else location.hash='course/'+id}else if(view==='record')renderRecord(c);else location.hash='courses'}
function renderCourses(){page(`<div class="hero"><div><div class="eyebrow">YOUR LEARNING SPACE</div><h1>Pick up a <em>thread.</em></h1><p class="intro">Every course is a world of connected ideas.<br>Choose one. We’ll keep the pieces together.</p></div><button class="secondary" id="newCourse">+ New course</button></div><div class="subhead"><span>YOUR COURSES</span><small>${courses().length} spaces · Fall semester</small></div><div class="course-grid">${courses().map(c=>`<a href="#course/${c.id}" class="course-card ${c.id==='cv'?'vision':''}">${art(c.id==='cv')}<div class="code">${esc(c.code)}</div><h2>${esc(c.name)}</h2><p>${esc(c.description||'A new space for your lectures and materials.')}</p><div class="card-bottom"><span>${c.lectures.length} lectures</span><span>${sources(c.id).length} sources</span><b>↗</b></div></a>`).join('')}</div><div class="library-note"><span>✧ &nbsp; Your ideas don’t live in isolation.</span><span>Start with a course. Add its sources.<br>Let the connections grow.</span></div>`,'<span>My courses</span>');$('#newCourse').onclick=newCourse}
function heading(c){return `<a class="back" href="#courses">← All courses</a><div class="hero course-hero"><div><div class="eyebrow">${esc(c.code)} &nbsp; / &nbsp; FALL 2026</div><h1>${esc(c.name)}<em>.</em></h1><p class="intro">${esc(c.teacher||'Your course workspace')} · ${c.lectures.length} lectures in your library</p></div><div class="hero-actions"><button class="secondary" data-source="${c.id}">+ Add sources</button><button class="primary" data-record="${c.id}">◉ Start a session</button></div></div>`}function tabs(c,active){return `<nav class="tabs"><a class="${active==='lectures'?'active':''}" href="#course/${c.id}">Overview & lectures <small>${c.lectures.length}</small></a><a class="${active==='sources'?'active':''}" href="#sources/${c.id}">Sources <small>${sources(c.id).length}</small></a></nav>`}
function overview(c){if(!c.lectures.length)return '';return `<section class="course-story"><div class="story-heading"><div class="eyebrow">THE BIGGER PICTURE</div><h2>${c.id==='ai'?'From copying actions<br>to understanding behavior.':c.id==='cv'?'From the world<br>to the image.':'A course, one idea at a time.'}</h2><p>${c.id==='ai'?'An editorial overview of this three-lecture collection. Each lecture gives the next one its starting point.':c.id==='cv'?'Your first three lectures, connected by the questions they explore.':'Your lecture collection will grow here as you add sessions.'}</p></div><div class="story-thread">${c.lectures.map((l,i)=>`<a href="#lecture/${c.id}/${l.id}"><span class="story-dot ${l.replay?'ready':''}"></span><small>0${l.id} · ${date(l.date)}</small><h3>${esc(l.subtitle||l.title)}</h3><p>${esc(l.title)}</p><span class="story-arrow">↗</span></a>`).join('')}</div></section>`}
function renderCourse(c){page(`${heading(c)}${tabs(c,'lectures')}${c.id==='ai'?`<div class="continue"><div class="number">02</div><div class="resume-text"><div class="eyebrow"><i></i> CURRENT DEMO LECTURE</div><h2>When imitation fails.</h2><p>DAgger · 7 moments · Original slides & transcript excerpts</p></div><a class="primary" href="lecture.html">Enter the thread ↗</a></div>`:''}${overview(c)}<div class="subhead"><span>THE LECTURE COLLECTION</span><small>Titles and dates from your course library</small></div>${c.lectures.length?`<div class="lecture-list">${c.lectures.map(l=>`<a href="#lecture/${c.id}/${l.id}" class="lecture-row"><span class="lecture-number">${String(l.id).padStart(2,'0')}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.subtitle)} · ${sources(c.id,l.id).filter(s=>s.lecture!=='all').length} lecture sources</p></div><time>${date(l.date)}, 2026</time><span class="badge ${l.replay?'':'dim'}">${l.replay?'<i class="dot"></i> Replay ready':'Placeholder'}</span><span class="arrow">↗</span></a>`).join('')}</div>`:'<div class="empty-state">Your first thread starts here. Add course sources, then preview a session.</div>'}<div class="source-preview"><div><b>One course. A shared foundation.</b><p>Course links and PDFs stay connected to the lectures they belong to.</p></div><a href="#sources/${c.id}">Explore ${sources(c.id).length} sources ↗</a></div>${foot()}`,`<a href="#courses">My courses</a><span>/ ${esc(c.name)}</span>`)}
function sourceRow(s,c){const l=c.lectures.find(l=>l.id===s.lecture);return `<article class="source-row"><div class="source-type">${s.pdf||s.file?'PDF':'LINK'}</div><div class="source-body"><h3>${esc(s.title)}</h3><p>${esc(s.kind)} · ${s.lecture==='all'?'Course-wide':`Lecture ${esc(s.lecture)}${l?' · '+esc(l.title):''}`}</p><p>${s.file?'Saved in this browser · Assigned by you':s.pdf?'Bundled PDF · Matched to local index':s.custom?'Awaiting ingestion · URL format checked':'Reference link · Not crawled'}</p>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(new URL(s.url).hostname)} ↗</a>`:''}</div><div class="source-actions">${s.pdf||s.file?`<button data-pdf="${s.id}">Open ↗</button>`:`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Visit ↗</a>`}${s.custom?`<button data-remove="${s.id}" aria-label="Remove ${esc(s.title)}">×</button>`:''}</div></article>`}function sourceList(c,l){let arr=sources(c.id,l);if(!l&&filter!=='All')arr=arr.filter(s=>s.kind===filter);return arr.length?`<div class="source-list">${arr.map(s=>sourceRow(s,c)).join('')}</div>`:'<div class="empty-state">No sources in this view yet. Add a PDF or course link.</div>'}
function renderLecture(c,l){page(`<a class="back" href="#course/${c.id}">← ${esc(c.name)}</a><div class="lecture-detail-top"><div><div class="eyebrow">${esc(c.code)} / LECTURE ${String(l.id).padStart(2,'0')} / ${date(l.date).toUpperCase()}, 2026</div><h1>${esc(l.title)}<em>.</em></h1><p class="intro">${esc(l.subtitle)} · ${esc(c.teacher)}</p></div>${l.replay?'<a class="primary" href="lecture.html">Open lecture timeline ↗</a>':`<button class="secondary" data-record="${c.id}" data-lecture="${l.id}">◉ Preview session</button>`}</div>${l.replay?`<div class="continue"><div class="number">↝</div><div class="resume-text"><div class="eyebrow"><i></i> THE THREAD IS READY</div><h2>Rewind through the ideas.</h2><p>Distribution shift → compounding errors → DAgger → recovery</p></div><a class="secondary" href="lecture.html">Resume at 33:10 ↗</a></div>`:`<div class="lecture-empty"><span class="empty-symbol">↝</span><div><h3>A place for the next thread.</h3><p>This lecture is a placeholder. Its title, date, and available source links are here; no timeline or summary has been generated.</p></div></div>`}<div class="provenance"><div><small>01 · ORIGIN</small><b>Course sources</b><p>Website / local PDFs</p></div><span>→</span><div><small>02 · ASSOCIATION</small><b>Lecture ${esc(l.id)}</b><p>${sources(c.id,l.id).length} linked sources</p></div><span>→</span><div><small>03 · CONTEXT</small><b>${l.replay?'Grounded moments':'Lecture placeholder'}</b><p>${l.replay?'Slides + transcript':'Ready for future content'}</p></div></div><div class="sources-layout"><section><div class="subhead"><span>LECTURE MATERIALS</span><small>Click a PDF to open it</small></div>${sourceList(c,l.id)}<p class="source-footnote">Associations are seeded from your local library. No automatic website crawl has run.</p></section><aside class="side-card"><div class="eyebrow">BUILD THE CONTEXT</div><h3>Every source has a place.</h3><p>Add a slide deck, paper, or link directly to this lecture. Course-wide sources appear in every lecture.</p><button class="secondary" data-source="${c.id}" data-lecture="${l.id}">+ Add to this lecture</button><a class="secondary" href="#sources/${c.id}">Course sources ↗</a></aside></div>${foot()}`,`<a href="#course/${c.id}">${esc(c.name)}</a><span>/ Lecture ${esc(l.id)}</span>`)}
function renderSources(c){page(`${heading(c)}${tabs(c,'sources')}<div class="sources-layout"><section><div class="source-toolbar"><div class="filters">${['All','Slides','Required','Optional','Website'].map(f=>`<button data-filter="${f}" class="${filter===f?'selected':''}">${f}</button>`).join('')}</div><span class="count">${sources(c.id).length} sources</span></div>${sourceList(c)}<p class="source-footnote">Added links await ingestion. Format checks do not validate a page’s contents. PDFs you add are stored only in this browser.</p></section><aside class="side-card"><div class="eyebrow">GIVE RECALL CONTEXT</div><h3>Bring your course in.</h3><p>A website, a slide deck, a paper. Start with whatever you have.</p><label class="drop-zone" id="quickDrop"><div class="upload-symbol">↥</div><strong>Drop a PDF here</strong><p>or choose a file · up to 25 MB</p><input type="file" id="quickFile" accept="application/pdf,.pdf" aria-label="Choose course PDF"></label><button class="secondary" data-link="${c.id}">↗ Add a website or link</button><div class="binding">Sources → lectures → understanding<span>You choose the lecture. AI matching and scraping are future integrations.</span></div></aside></div>${foot()}`,`<a href="#course/${c.id}">${esc(c.name)}</a><span>/ Sources</span>`);$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderSources(c)});$('#quickFile').onchange=e=>{if(e.target.files[0])addPDF(c.id,'all',e.target.files[0])};wireDrop($('#quickDrop'),f=>addPDF(c.id,'all',f))}
function bind(){$$('[data-source]').forEach(b=>b.onclick=()=>addPDF(b.dataset.source,b.dataset.lecture||'all'));$$('[data-link]').forEach(b=>b.onclick=()=>addLink(b.dataset.link));$$('[data-pdf]').forEach(b=>b.onclick=()=>openPDF(b.dataset.pdf));$$('[data-remove]').forEach(b=>b.onclick=()=>{userSources=userSources.filter(s=>s.id!==b.dataset.remove);save();render();notify('Source removed from the workspace.')});$$('[data-record]').forEach(b=>b.onclick=()=>setupRecord(b.dataset.record,b.dataset.lecture))}
function lectureOptions(c,l){return `<option value="all" ${l==='all'?'selected':''}>Entire course · shared context</option>${c.lectures.map(x=>`<option value="${x.id}" ${x.id===l?'selected':''}>Lecture ${x.id} · ${esc(x.title)}</option>`).join('')}`}
function wireDrop(el,fn){el.ondragover=e=>{e.preventDefault();el.classList.add('dragover')};el.ondragleave=()=>el.classList.remove('dragover');el.ondrop=e=>{e.preventDefault();el.classList.remove('dragover');if(e.dataTransfer.files[0])fn(e.dataTransfer.files[0])}}
function addPDF(cid,l='all',initial=null){const c=getCourse(cid);let file=initial;modal(`<div class="eyebrow">${esc(c.name).toUpperCase()} · ADD CONTEXT</div><h2>A home for every source.</h2><p>Add a PDF and choose where it belongs. The file stays in this browser.</p><form id="pdfForm"><label class="drop-zone" id="fileDrop"><div class="upload-symbol">↥</div><strong>Drop your PDF here</strong><p>or choose a file · PDF only · 25 MB maximum</p><input id="pdfInput" type="file" accept="application/pdf,.pdf" aria-label="Choose PDF"></label><div id="chosenFile"></div><label class="form-field"><span>Attach to</span><select id="association">${lectureOptions(c,l)}</select><small>You confirm the lecture. No AI content matching has run.</small></label><label class="form-field"><span>Material type</span><select id="kind"><option>Slides</option><option>Required</option><option>Optional</option></select></label><div class="message" id="formError" role="status"></div><div class="form-actions"><button type="button" class="secondary" id="insteadLink">Add a link instead ↗</button><button class="primary" type="submit" id="savePDF">Save PDF ↗</button></div></form>`);const show=()=>{$('#chosenFile').innerHTML=file?`<div class="file-chip">▤ ${esc(file.name)} · ${(file.size/1048576).toFixed(1)} MB</div>`:''};show();$('#pdfInput').onchange=e=>{file=e.target.files[0]||null;show()};wireDrop($('#fileDrop'),f=>{file=f;show()});$('#insteadLink').onclick=()=>addLink(cid,$('#association').value);$('#pdfForm').onsubmit=async e=>{e.preventDefault();if(!file||file.size>25*1048576){$('#formError').textContent='Choose a PDF no larger than 25 MB.';return}const sig=new TextDecoder().decode(await file.slice(0,1024).arrayBuffer());if(!sig.includes('%PDF-')){$('#formError').textContent='This file does not appear to be a valid PDF.';return}const s={id:uid(),course:cid,lecture:$('#association').value,kind:$('#kind').value,title:file.name,file:true,custom:true};$('#savePDF').disabled=true;try{await putFile(s.id,file);userSources.push(s);save();$('#dialog').close();render();notify('PDF saved and linked to your selected context.')}catch{$('#formError').textContent='Browser storage could not save this PDF. Try a smaller file or allow site storage.';$('#savePDF').disabled=false}}}
function addLink(cid,l='all'){const c=getCourse(cid);modal(`<div class="eyebrow">${esc(c.name).toUpperCase()} · CONNECT A SOURCE</div><h2>Start with a link.</h2><p>Save a course website or document URL. Scraping, PDF discovery, and content validation are not connected yet.</p><form id="linkForm"><label class="form-field"><span>Website or document URL</span><input type="url" id="linkURL" required placeholder="https://your-course.edu/schedule"></label><label class="form-field"><span>Source name (optional)</span><input id="linkTitle" maxlength="150" placeholder="Course schedule or reading"></label><label class="form-field"><span>Attach to</span><select id="linkAssociation">${lectureOptions(c,l)}</select></label><label class="form-field"><span>Material type</span><select id="linkKind"><option>Website</option><option>Slides</option><option>Required</option><option>Optional</option></select></label><div class="message" id="linkError" role="status"></div><div class="form-actions"><span class="form-note">URL format checked · Content not fetched</span><button class="primary" type="submit">Add source ↗</button></div></form>`);$('#linkForm').onsubmit=e=>{e.preventDefault();let url;try{url=new URL($('#linkURL').value);if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw Error()}catch{$('#linkError').textContent='Enter an http or https URL without embedded credentials.';return}userSources.push({id:uid(),course:cid,lecture:$('#linkAssociation').value,kind:$('#linkKind').value,title:$('#linkTitle').value.trim()||url.hostname,url:url.href,custom:true});save();$('#dialog').close();render();notify('Link saved. Automatic ingestion is not connected yet.')}}
function newCourse(){modal(`<div class="eyebrow">A NEW THREAD</div><h2>Make room for a course.</h2><p>Start with its name. Bring in its sources whenever you’re ready.</p><form id="courseForm"><label class="form-field"><span>Course name</span><input id="courseName" required maxlength="100" placeholder="e.g. Machine Learning"></label><label class="form-field"><span>Course code</span><input id="courseCode" maxlength="40" placeholder="e.g. COMPSCI 589"></label><div class="form-actions"><span class="form-note">Saved in this browser</span><button class="primary" type="submit">Create course ↗</button></div></form>`);$('#courseForm').onsubmit=e=>{e.preventDefault();const name=$('#courseName').value.trim();if(!name)return;const c={id:uid(),name,code:$('#courseCode').value.trim()||'MY COURSE',teacher:'Your course workspace',lectures:[]};userCourses.push(c);save();$('#dialog').close();location.hash='course/'+c.id}}
function setupRecord(cid,lid){const c=getCourse(cid),l=c.lectures.find(l=>l.id===lid);modal(`<div class="eyebrow">${esc(c.name).toUpperCase()} · SESSION PREVIEW</div><h2>Ready when you are.</h2><p>This is a recording interface preview. No microphone is accessed and no audio is captured.</p><form id="recordForm"><label class="form-field"><span>Session title</span><input id="sessionTitle" required maxlength="150" value="${esc(l?.title||'New lecture')}"></label><label class="form-field"><span>Use materials from</span><select id="sessionLecture">${lectureOptions(c,lid||'all')}</select></label><div class="form-actions"><span class="form-note">Microphone & transcription not connected</span><button class="primary" type="submit">Begin demo session ↗</button></div></form>`);$('#recordForm').onsubmit=e=>{e.preventDefault();recording={course:cid,title:$('#sessionTitle').value.trim(),lecture:$('#sessionLecture').value,started:Date.now()};$('#dialog').close();location.hash='record/'+cid}}
function renderRecord(c){if(!recording||recording.course!==c.id){location.hash='course/'+c.id;return}page(`<a class="back" href="#course/${c.id}">← Course workspace</a><div class="record-shell"><div class="eyebrow"><i></i> UI SIMULATION · NO AUDIO CAPTURE</div><h1>${esc(recording.title)}<em>.</em></h1><div class="record-orb"><b id="recordClock">00:00</b></div><p>In a connected session, the ideas being discussed would begin to appear here.</p><span class="badge">${sources(c.id,recording.lecture==='all'?undefined:recording.lecture).length} sources available as context</span><div><button class="primary" id="endRecord">■ End demo session</button></div><p class="form-note">No recording or transcript is created by this prototype.</p></div>`,`<a href="#course/${c.id}">${esc(c.name)}</a><span>/ Session</span>`);clearInterval(recordTimer);recordTimer=setInterval(()=>{const n=Math.floor((Date.now()-recording.started)/1000);if($('#recordClock'))$('#recordClock').textContent=`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`},1000);$('#endRecord').onclick=()=>{clearInterval(recordTimer);recording=null;location.hash='course/'+c.id;notify('Demo ended. No audio was recorded.')}}
let dbPromise;function db(){return dbPromise??=new Promise((resolve,reject)=>{const q=indexedDB.open('recall-files',1);q.onupgradeneeded=()=>q.result.createObjectStore('pdfs');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}async function putFile(id,f){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('pdfs','readwrite');t.objectStore('pdfs').put(f,id);t.oncomplete=resolve;t.onerror=()=>reject(t.error)})}async function getFile(id){const d=await db();return new Promise((resolve,reject)=>{const q=d.transaction('pdfs').objectStore('pdfs').get(id);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}async function openPDF(id){const s=[...baseSources,...userSources].find(s=>s.id===id);if(!s)return;let url=s.pdf;try{if(s.file){const f=await getFile(s.id);if(!f){notify('PDF unavailable in browser storage. Please add it again.');return}url=URL.createObjectURL(f);blobURLs.push(url)}modal(`<div class="pdf-header"><h2>${esc(s.title)}</h2><a href="${esc(url)}" target="_blank" rel="noopener">Open in a new tab ↗</a></div><iframe class="pdf-frame" title="${esc(s.title)}" src="${esc(url)}"></iframe><p class="pdf-help">If the embedded preview is unavailable, open the PDF in a new tab.</p>`,true)}catch{notify('Unable to access the stored PDF. Please add it again.')}}
$('#about').onclick=()=>modal('<div class="eyebrow">RECALL · WORKSPACE PREVIEW</div><h2>Your learning, connected.</h2><p>Courses hold lectures. Sources belong to the whole course or to one lecture. AI Alignment Lecture 02 opens the immersive timeline; other lectures are placeholders.</p><p>Uploaded PDFs and added course metadata stay in this browser. The six bundled PDFs are copied from your original library. Website scraping, AI matching, content validation, recording, and transcription are not connected.</p>');window.addEventListener('hashchange',()=>{filter='All';if(route()[0]!=='record')clearInterval(recordTimer);render()});render();
